package com.reellock.reellock.recovery

import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Throwaway interop check: a public key and signature generated by
 * tools/trusted_signer.js (Node's built-in crypto, SPKI DER public key,
 * DER ECDSA signature over SHA-256) against the exact Kotlin verifier
 * RecoveryManager uses. Confirms the two implementations actually agree on
 * wire format, since no Python/Node round trip could otherwise be checked
 * against the JVM side in one go.
 */
class NodeInteropTest {
    @Test
    fun `node-generated key and signature verify against the Kotlin implementation`() {
        val publicKeyBase64 =
            "MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEUXoTLU8mTc6kqa0pww9I+hg8XIyIey1n8d+is8f6/thgh0i+" +
                "J3nDie38Qxfu67jh4B/OYuRtz1tpxdIxnYtexA=="
        val signatureBase64 = "MEQCIFovJ1vePIILJWKf/S1G1QWJKPeCMDeAcQUXGcXdnkCfAiAV1o0oG2HYGHmY6EGLj+neUKtS9FbLbmCSnLwg8z4H8A=="
        val challenge = "nonce-abc|device-123|1|UNLOCK_CONFIG_EDIT|1234567890".toByteArray(Charsets.UTF_8)

        val publicKey = RecoveryCrypto.parsePublicKeyBase64(publicKeyBase64)
        assertTrue("public key failed to parse", publicKey != null)
        assertTrue("signature did not verify", RecoveryCrypto.verify(publicKey!!, challenge, signatureBase64))
    }
}
